breach.segment:
// Minimum samples: require ~5 minutes of data in the window
WHERE minutes >= 5
// Alert threshold: average connections as a percentage of max_connections.
// New connections are refused once max_connections (minus reserved superuser slots) is reached.
| WHERE conn_avg_pct >= 85
| KEEP database_id, conn_avg_pct, conn_peak_pct, avg_backends, max_backends, max_conn
| SORT conn_avg_pct DESC
| LIMIT 100
